// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address _recipient, uint256 _sendValue) public {
        // Bound the send value to avoid exceeding contract balance or overflow
        vm.assume(_recipient != address(0));
        vm.deal(address(c), _sendValue);
        // Call withdrawAll as owner (msg.sender == address(this))
        c.withdrawAll(_recipient);
        // The contract balance should be exactly 0 after a successful withdrawAll
        assertTrue(address(c).balance == 0);
    }
}

